function fewestReplacements(nums: number[]): number {
  const n = nums.length;
  const u = [...new Set(nums)];
  let best = 0;
  for (const s of u) {
    let keep = 0;
    for (const v of u) if (v >= s && v <= s + n - 1) keep++;
    best = Math.max(best, keep);
  }
  return n - best;
}

